-- MANTECH (new brand): T10 turbidity meter, PeCOD L50 COD/BOD analyzer, MT3 / MT4 pH systems, MT10 / MT30 / MT100 automated titrators (7 products).
-- From the MANTECH brochures. Photos: public/products/mantech/, logo: public/brands/mantech.png.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('MANTECH', 'mantech', 'https://mantech-inc.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Environmental Equipment', 'environmental-equipment', 6) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('MANTECH-T10', 'MANTECH T10 Turbidity Meter', 'mantech-t10-turbidity-meter-mantech-t10', 'The MANTECH T10 is a compact, IP67 turbidity meter measuring 0.02 to 1000 NTU with ratio nephelometric optics and only 30 mL of sample. MANTECH''s bottom-in, bottom-out sample design prevents carry-over and dilution. Use it on the bench, add a carrying case and batteries for field work, or add an autosampler to automate it with other parameters. MANTECH Pro™ software is included free.', '[["Measurement method", "Ratio of 90° nephelometric scatter to transmitted light"], ["Measuring modes", "Normal, signal averaging, fast settling"], ["Units", "NTU, EBC, FNU, FTU, TE/F"], ["Lamp", "Tungsten (white light) or LED 850 nm (IR)"], ["Method conformity", "EPA 180.1, ASTM D1889, SM 2130B (white light); ISO 7027, EN27027 (IR)"], ["Detector", "Silicon photocells at 90° and 180°"], ["Range", "0.02 to 1000 NTU / 0 to 250 EBC / 0 to 1000 FNU, TE/F, FTU / 0 to 1000 mg/L"], ["Resolution", "0.01 on lowest range"], ["Accuracy", "±1 % of reading (0 to 1000 NTU) plus stray light"], ["Repeatability", "±0.4 % of reading or ±0.003 NTU"], ["Stray light", "< 0.02 NTU"], ["Automatic reading", "User-defined intervals, 0 to 250 s"], ["Response time", "Programmable, 6 to 41 s"], ["Display", "LCD, 2 lines × 16 characters, multi-language"], ["Data logger", "Up to 1000 readings"], ["Software functions", "Result freezing, analyst and sample ID, calibration status, reminders and history, password"], ["Sample vial", "15 mL round borosilicate glass, 24.5 mm dia × 64 mm, with screw cap"], ["Power", "4 × AA batteries or USB (100 to 240 V adaptor)"], ["Output", "USB"], ["Operating conditions", "0 to 50 °C, max. 90 % humidity"], ["Enclosure", "IP67, lid open or closed"], ["Certifications", "CE / WEEE"], ["Dimensions", "114 × 198 × 83 mm"]]', '["Only 30 mL sample; non-destructive 2 to 3 minute analysis", "Bottom-in, bottom-out design prevents sample carry-over and dilution", "Low-end precision from 0.02 NTU", "Splash-resistant, compact handheld casing (IP67)", "White light or infrared lamp options", "Benchtop, portable (case and batteries) or fully automated with an autosampler", "MANTECH Pro™ software included free"]', 'environmental-equipment', '/products/mantech/t10-turbidity-meter.jpg'),
  ('MANTECH-PECOD-L50', 'MANTECH PeCOD® L50 COD/BOD Analyzer', 'mantech-pecod-l50-cod-bod-analyzer-mantech-pecod-l50', 'The MANTECH PeCOD® L50 is a rapid, safe and green COD/BOD analyzer. It gives results in 10 minutes or less, uses salt- and sugar-based solutions that can go down the drain instead of hazardous dichromate waste, and can be run by staff who are not water-quality specialists. Conforms to ASTM International method D8084.', '[["Model", "PeCOD® L50"], ["Parameters", "COD, BOD (correlated)"], ["Analysis time", "10 minutes or less"], ["Method", "ASTM D8084"], ["Reagents", "Salt- and sugar-based, non-hazardous (drain disposal)"], ["Interface", "Built-in display and keypad"]]', '["Results in 10 minutes or less for fast treatment and process decisions", "No hazardous waste: green reagents that can be poured down the drain", "Easy enough for operators and engineers to run", "Conforms to ASTM D8084; hundreds of analyzers in use"]', 'environmental-equipment', '/products/mantech/pecod-l50.jpg'),
  ('MANTECH-MT3', 'MANTECH MT3 Automated pH Meter System', 'mantech-mt3-automated-ph-meter-system-mantech-mt3', 'The MANTECH MT3 automatically measures pH, or other ions such as fluoride, using stability criteria you define, and records every result in MANTECH Pro™ for automatic export to your LIMS. Includes pH probe, MiniHub™ interface and analysis stand that takes any vessel size; a software-controlled paddle stirrer and USB temperature probe are optional.', '[["Includes", "TitraPRO4 pH probe, MiniHub™ interface, analysis stand"], ["Options", "Software-controlled variable-speed paddle stirrer, USB temperature probe"], ["Parameters", "pH, other ions (e.g. fluoride); more MANTECH parameters can be added"], ["MiniHub™ interface", "6 digital outputs / 6 digital inputs; 4 galvanically separated BNC electrode ports, 3 variable-speed 24 V stirrers; Ethernet/IP; 15 × 10 × 5 cm"], ["Probe stand & holder", "Height-adjustable, takes any tube, cup or beaker; 27 × 18 × 16.5 cm"], ["pH electrode", "TitraPRO4, 0 to 14 pH, 3-point calibration in 30 s, pH value in ≤ 10 s; BNC/S7; 12 × 120 mm"], ["pH method", "EPA 150.1, 150.2; SM 4500-H+ B; ASTM D 1293; ISO 10523 (water, soil); RSD ±0.05"], ["Software", "MANTECH Pro™ (Windows 10 / 11 Pro), included"]]', '["Automatic pH measurement with user-defined stability criteria", "Accommodates any vessel size", "Fast 30-second 3-point calibration with re-calibration reminders", "MANTECH Pro™ software included: shortcut buttons, step-by-step prompts, live results and LIMS import/export", "Add more MANTECH parameters (pH, alkalinity, conductivity, turbidity, COD and more) to the same station"]', 'environmental-equipment', '/products/mantech/mt3.jpg'),
  ('MANTECH-MT4', 'MANTECH MT4 Automated pH Measurement & Adjustment System', 'mantech-mt4-automated-ph-measurement-adjustment-system-mantech-mt4', 'The MANTECH MT4 measures and records pH like the MT3 and goes one step further: if a sample is outside your target range, IntelliPeri™ pumps (or burets) automatically add acid or base until the desired pH is reached. Ideal for BOD and PeCOD sample preparation.', '[["Includes", "pH probe, paddle stirrer, temperature probe, 2 dispense tips, MiniHub™ interface, analysis stand, 1 or 2 IntelliPeri™ pumps or burets"], ["Function", "Automatic pH adjustment with acid and/or base"], ["IntelliPeri™ peristaltic pump", "12.5 to 860 mL/min; software-controlled speed, direction and autocalibration; USB; 18 × 15 × 15 cm"], ["MiniHub™ interface", "6 digital outputs / 6 digital inputs; 4 galvanically separated BNC electrode ports, 3 variable-speed 24 V stirrers; Ethernet/IP; 15 × 10 × 5 cm"], ["Probe stand & holder", "Height-adjustable, takes any tube, cup or beaker; 27 × 18 × 16.5 cm"], ["pH electrode", "TitraPRO4, 0 to 14 pH, 3-point calibration in 30 s, pH value in ≤ 10 s; BNC/S7; 12 × 120 mm"], ["pH method", "EPA 150.1, 150.2; SM 4500-H+ B; ASTM D 1293; ISO 10523 (water, soil); RSD ±0.05"], ["Software", "MANTECH Pro™ (Windows 10 / 11 Pro), included"]]', '["Automatically adjusts samples to your target pH", "Ideal for BOD and PeCOD sample preparation", "Accommodates any vessel size", "MANTECH Pro™ software included: shortcut buttons, step-by-step prompts, live results and LIMS import/export", "Add more MANTECH parameters (pH, alkalinity, conductivity, turbidity, COD and more) to the same station"]', 'environmental-equipment', '/products/mantech/mt4.jpg'),
  ('MANTECH-MT10', 'MANTECH MT10 Automated Environmental Titrator & Multi-Parameter Analyzer', 'mantech-mt10-automated-environmental-titrator-multi-parameter-analyzer-mantech-mt10', 'The MANTECH MT10 is an automated environmental titrator and multi-parameter analyzer for water, soil, food and beverage testing. Small sample volumes keep operating costs low. Controlled by the included MANTECH Pro™ software.', '[["Model", "MT10"], ["Type", "Automated titrator / multi-parameter analyzer"], ["Autosampler", "AutoMax 400 XYZ autosampler (pictured: AM401; 1 to 5 rack options)"], ["Applications", "Water, soil, food and beverage"], ["Software", "MANTECH Pro™ (Windows 10 / 11 Pro), included"]]', '["Lowest operating costs thanks to small sample volumes", "AutoMax 400 XYZ autosampler with self-lubricating axes; add rush samples during a run", "MANTECH Pro™ software included: shortcut buttons, step-by-step prompts, live results and LIMS import/export", "Add more MANTECH parameters (pH, alkalinity, conductivity, turbidity, COD and more) to the same station"]', 'environmental-equipment', '/products/mantech/mt10.jpg'),
  ('MANTECH-MT30', 'MANTECH MT30 Automated Environmental Titrator & Multi-Parameter Analyzer', 'mantech-mt30-automated-environmental-titrator-multi-parameter-analyzer-mantech-mt30', 'The MANTECH MT30 is an automated environmental titrator and multi-parameter analyzer for water, soil, food and beverage testing. Software-controlled, bi-directional IntelliRinse™ keeps probes clean between samples. Controlled by the included MANTECH Pro™ software.', '[["Model", "MT30"], ["Type", "Automated titrator / multi-parameter analyzer"], ["Autosampler", "AutoMax 400 XYZ autosampler (pictured: AM402; 1 to 5 rack options)"], ["Applications", "Water, soil, food and beverage"], ["Software", "MANTECH Pro™ (Windows 10 / 11 Pro), included"]]', '["Small sample volumes lower operating costs", "IntelliRinse™ bi-directional probe rinsing prevents cross-contamination", "Accommodates any sample container", "AutoMax 400 XYZ autosampler with self-lubricating axes; add rush samples during a run", "MANTECH Pro™ software included: shortcut buttons, step-by-step prompts, live results and LIMS import/export", "Add more MANTECH parameters (pH, alkalinity, conductivity, turbidity, COD and more) to the same station"]', 'environmental-equipment', '/products/mantech/mt30.jpg'),
  ('MANTECH-MT100', 'MANTECH MT100 Automated Environmental Titrator & Multi-Parameter Analyzer', 'mantech-mt100-automated-environmental-titrator-multi-parameter-analyzer-mantech-mt100', 'The MANTECH MT100 is an automated environmental titrator and multi-parameter analyzer for water, soil, food and beverage testing. Automated pipetting delivers sample accurately to the analysis vessel, so two or more titration methods can run from a single tube. Controlled by the included MANTECH Pro™ software.', '[["Model", "MT100"], ["Type", "Automated titrator / multi-parameter analyzer"], ["Autosampler", "AutoMax 400 XYZ autosampler (pictured: AM401; 1 to 5 rack options)"], ["Applications", "Water, soil, food and beverage"], ["Software", "MANTECH Pro™ (Windows 10 / 11 Pro), included"]]', '["Automated pipetting eliminates human error; several titrations from one tube", "IntelliRinse™ bi-directional probe rinsing prevents cross-contamination", "Small sample volumes lower operating costs", "AutoMax 400 XYZ autosampler with self-lubricating axes; add rush samples during a run", "MANTECH Pro™ software included: shortcut buttons, step-by-step prompts, live results and LIMS import/export", "Add more MANTECH parameters (pH, alkalinity, conductivity, turbidity, COD and more) to the same station"]', 'environmental-equipment', '/products/mantech/mt100.jpg')
) as v(sku, name, slug, description, specs, features, cat, image_url)
join categories c on c.slug = v.cat
cross join (select id from brands where slug = 'mantech') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select count(*) as products from products p join brands b on b.id = p.brand_id where b.slug = 'mantech' and p.is_active;
